#include "room.hpp"
#include <iostream>
#include <stdexcept>
#include <algorithm>
using namespace biglybtc;namespace chat=services::msgsync;namespace crypto=plugins::msgsync;
void need(bool good,const char* label){if(!good){throw std::runtime_error(label);}}
template<class T,class E>T take(std::expected<T,E> value){need(value.has_value(),"Generated moderation operation");return std::move(*value);}
std::string bytes(std::string_view s){return std::to_string(s.size())+":"+std::string(s);}
struct Author {decltype(take(crypto::generateMessageIdentity())) identity;crypto::MessageSigner signer;chat::Uid uid{};explicit Author(unsigned n):identity(take(crypto::generateMessageIdentity())),signer(take(crypto::MessageSigner::open(identity.publicKey,identity.privateKey))){uid[0]=static_cast<unsigned char>(n);}};
chat::Room room(unsigned n){Author a(n);return take(chat::Room::open("Generated moderation room",a.uid,std::move(a.signer),"de"));}
chat::Message message(Author& a,unsigned n,std::string history){auto m=take(chat::signMessage(a.signer,a.uid,"d3:msg"+bytes("Generated message "+std::to_string(n))+"4:nick9:Generatede"));m.publicKey=a.identity.publicKey;m.encodedContact="de";m.history=std::move(history);return m;}
std::string wrap(chat::SyncReply reply){auto keys=take(crypto::deriveChannelKeys(std::span(reinterpret_cast<const std::uint8_t*>("Generated moderation room"),25)));auto plain=take(chat::encodeSyncReply(reply));return take(crypto::encrypt(crypto::Kind::General,keys.general,std::span(reinterpret_cast<const std::uint8_t*>(plain.data()),plain.size())));}
int main(){try{
 auto target=room(1);Author marked(2),relay(3);chat::SyncReply batch;
 for(unsigned n=0;n<4;++n){batch.messages.push_back(message(marked,n,"ABCD"));}auto first=wrap(batch);need(take(target.receive(first,100000)).added==4,"Four signed messages");need(!take(target.canMarkSpammer(marked.identity.publicKey,100000)),"Four-message threshold");need(!target.setSpammer(marked.identity.publicKey,true,100000),"Under-threshold mark accepted");need(!take(target.canMarkSpammer(target.publicKey(),100000)),"Self moderation");
 batch.messages={message(marked,4,"ABCD")};need(take(target.receive(wrap(batch),100000)).added==1,"Fifth signed message");need(take(target.canMarkSpammer(marked.identity.publicKey,100000)),"Five-message threshold");need(bool(target.setSpammer(marked.identity.publicKey,true,100000)),"Mark actual sender");auto rows=take(target.messages(100000));need(rows.size()==5&&std::ranges::all_of(rows,[](const auto& m){return m.spammer&&m.localError.empty();}),"Mark deleted or relabelled signed messages");
 // An unmarked author traversing a suspect relay becomes a local error report;
 // the authenticated payload, ledger and relay copy remain valid and intact.
 batch.messages={message(relay,5,"ABCD")};auto envelope=wrap(batch);need(take(target.receive(envelope,100001)).added==1,"Relay message retained");rows=take(target.messages(100001));need(rows.back().localError=="Message ignored due to spam/flooding"&&!rows.back().spammer&&rows.back().nickname=="Generated"&&rows.back().text=="Generated message 5","Local report/signature projection differs");auto duplicate=take(target.receive(envelope,100002));need(duplicate.added==0&&duplicate.duplicates==1,"Duplicate moderation changed ledger");
 auto history=take(target.exportHistory(100002));auto document=take(core::Document::parse(history));const auto* saved=document.find("messages");need(saved&&saved->children.back().find("l"),"Per-message local report missing");auto restored=room(4);need(take(restored.importHistory(history,100002)).added==6,"Encrypted history restoration");rows=take(restored.messages(100002));need(!rows.front().spammer&&!restored.spammer(marked.identity.publicKey),"Runtime Spam restored from history");need(rows.back().localError=="Message ignored due to spam/flooding","Local report was not restored");
 auto neighbour=room(5);for(int i=0;i<10&&neighbour.retainedMessages()<6;++i){auto req=take(neighbour.request(100003));auto answer=take(target.answer(req,100003));take(neighbour.receive(answer,100003));}rows=take(neighbour.messages(100003));need(rows.size()==6&&rows.back().localError.empty()&&rows.back().text=="Generated message 5","Local moderation leaked into signed relay data");
 batch.messages={message(marked,6,"")};need(take(target.receive(wrap(batch),100004)).added==1,"Direct marked identity retained");rows=take(target.messages(100004));need(rows.back().spammer&&rows.back().localError.empty(),"Direct public key wrongly became relay ban");auto forged=message(relay,7,"ABCD");forged.content="d3:msg6:forgede";batch.messages={forged};auto bad=take(target.receive(wrap(batch),100005));need(bad.added==0&&bad.rejected==1,"Invalid signature altered spam state");need(bool(target.setSpammer(marked.identity.publicKey,false,100006)),"Unmark failed");batch.messages={message(relay,8,"ABCD")};take(target.receive(wrap(batch),100006));rows=take(target.messages(100006));need(rows.back().localError.empty()&&!rows.front().spammer,"Unmark did not recompute filter");
 // History uses SHA1(actual relay contact),4 bytes per hop,80-byte FIFO bound.
 auto token=take(chat::relayHistory(std::string(80,'x'),{"127.124.19.1:45321",true}));need(token.size()==80&&token.substr(4)==std::string(76,'x'),"Relay history cap");need(token.substr(0,4)==std::string("\x0a\x11\xce\x41",4),"Java relay contact digest");need(take(chat::relayHistory("ABCD",{"",false}))=="ABCD","Quiet channel added relay history");need(!chat::relayHistory(std::string(81,'x'),{"127.124.19.1:45321",true}),"Oversize relay history accepted");
 std::cout<<"PASS signed-room moderation: threshold, full signed identity, local reports, encrypted history, relay preservation, unmark and busy history bounds\n";return 0;
}catch(const std::exception& ex){std::cerr<<"FAIL "<<ex.what()<<'\n';return 1;}}
